style.css:
@-moz-document domain("open.spotify.com") {
/* Smooth transitions for all elements */
  * {
    transition: color 0.3s ease, background-color 0.3s ease;
  }

  /* Base page background (main content area) */
  body {
    background-color: #ffffff !important;
  }

  /* Left sidebar styling */
  div.Root__top-container > nav.Root__nav-bar {
    background-color: #ffe4eb !important; /* light pink background */
  }
  div.Root__top-container > nav.Root__nav-bar li a {
    color: #8F6251 !important; /* chocolate brown text */
  }
  div.Root__top-container > nav.Root__nav-bar li a svg {
    fill: #F8C2D0 !important; /* pink icons */
    color: #F8C2D0 !important;
  }
  div.Root__top-container > nav.Root__nav-bar li a:hover {
    background-color: #fff0f5 !important; /* pale pink hover */
  }

  /* Top navigation bar and search */
  div.Root__top-container {
    background-color: #ffe4eb !important; /* soft pink top bar */
    color: #8F6251 !important;             /* brown text */
  }
  input[data-testid="search-input"] {
    background-color: #ffe4eb !important; /* search bar pink */
    color: #8F6251 !important;            /* search text brown */
  }
  input[data-testid="search-input"]::placeholder {
    color: #8F6251 !important;            /* placeholder brown */
  }

  /* Global text color override */
  h1, h2, h3, h4, h5, h6,
  p, a, span, label, input, textarea, button, li {
    color: #8F6251 !important; /* all text in brown */
  }

  /* Player control bar (bottom) */
  div.Root__now-playing-bar,
  div.Root__now-playing-bar footer {
    background-color: #ffe4eb !important; /* pink background */
  }
  div.Root__now-playing-bar, div.Root__now-playing-bar * {
    color: #8F6251 !important; /* brown text in player */
  }
  /* Control icons (play, prev/next, shuffle, repeat, etc.) */
  button[data-testid^="control-button-"] svg {
    fill: #F8C2D0 !important; /* pink icon color */
    color: #F8C2D0 !important;
  }
  /* Lyrics and queue buttons if present */
  button[data-testid="lyrics-button"] svg,
  button[data-testid="control-button-queue"] svg {
    fill: #F8C2D0 !important;
  }

  /* Hover states for links and buttons */
  a:hover, button:hover {
    background-color: #fff0f5 !important; /* pale pink hover */
  }
}
